{
    var hcv = RGBtoHCV(rgb);
    var l = hcv.z - hcv.y * 0.5;
    var s = hcv.y / (1.0 - abs(l * 2.0 - 1.0) + czm_epsilon7);
    return vec3<f32>(hcv.x, s, l);
}
