    var q0 = vec3<f32>( dpdx( eye_pos.x ), dpdx( eye_pos.y ), dpdx( eye_pos.z ) );
    var q1 = vec3<f32>( dpdy( eye_pos.x ), dpdy( eye_pos.y ), dpdy( eye_pos.z ) );
    var st0 = dpdx( uv.xy );
    var st1 = dpdy( uv.xy );
    if(fNormalLength < 0.5) {
         return surf_norm;
    }
    var scale = sign( st1.y * st0.x - st0.y * st1.x );
    var S = normalize( ( q0 * st1.y - q1 * st0.y ) * scale );
    var T = normalize( ( - q0 * st1.x + q1 * st0.x ) * scale );
    var N = normalize( surf_norm );
    var tsn = mat3x3<f32>( S, T, N );

    var tempN = mapN * 2.0 - 1.0;
    var flip = f32( gl_FrontFacing ) * 2.0 - 1.0;
    var normMapN = vec3(tempN.x  * Material.uNormalTextureScale * flip, tempN.y * Material.uNormalTextureScale * flip, tempN.z);
