    var val_se : vec4<f32> = textureSample(uGlobalNormalTexture, uGlobalNormalTextureSampler, tex_se.xy);
    val_se.x = ((val_se.xyz * 2.0) - 1.0).x;
    val_se.y = ((val_se.xyz * 2.0) - 1.0).y;
    val_se.z = ((val_se.xyz * 2.0) - 1.0).z;
