    var Gy = mat3x3( -1, 0, 1, -2, 0, 2, -1, 0, 1 ); // y direction kernel
    
    var tx0y0 = czm_unpackDepth(textureSample( uGlobalDepthTexture, uGlobalDepthTextureSampler, center + texel * vec2( -1, -1 ) ));
    var tx0y1 = czm_unpackDepth(textureSample( uGlobalDepthTexture, uGlobalDepthTextureSampler, center + texel * vec2( -1,  0 ) ));
    var tx0y2 = czm_unpackDepth(textureSample( uGlobalDepthTexture, uGlobalDepthTextureSampler, center + texel * vec2( -1,  1 ) ));
    var tx1y0 = czm_unpackDepth(textureSample( uGlobalDepthTexture, uGlobalDepthTextureSampler, center + texel * vec2(  0, -1 ) ));
    var tx1y1 = czm_unpackDepth(textureSample( uGlobalDepthTexture, uGlobalDepthTextureSampler, center + texel * vec2(  0,  0 ) ));
    var tx1y2 = czm_unpackDepth(textureSample( uGlobalDepthTexture, uGlobalDepthTextureSampler, center + texel * vec2(  0,  1 ) ));
    var tx2y0 = czm_unpackDepth(textureSample( uGlobalDepthTexture, uGlobalDepthTextureSampler, center + texel * vec2(  1, -1 ) ));
    var tx2y1 = czm_unpackDepth(textureSample( uGlobalDepthTexture, uGlobalDepthTextureSampler, center + texel * vec2(  1,  0 ) ));
    var tx2y2 = czm_unpackDepth(textureSample( uGlobalDepthTexture, uGlobalDepthTextureSampler, center + texel * vec2(  1,  1 ) ));
    
    var valueGx = Gx[0][0] * tx0y0 + Gx[1][0] * tx1y0 + Gx[2][0] * tx2y0 +
        Gx[0][1] * tx0y1 + Gx[1][1] * tx1y1 + Gx[2][1] * tx2y1 +
        Gx[0][2] * tx0y2 + Gx[1][2] * tx1y2 + Gx[2][2] * tx2y2;
        
    var valueGy = Gy[0][0] * tx0y0 + Gy[1][0] * tx1y0 + Gy[2][0] * tx2y0 +
        Gy[0][1] * tx0y1 + Gy[1][1] * tx1y1 + Gy[2][1] * tx2y1 +
        Gy[0][2] * tx0y2 + Gy[1][2] * tx1y2 + Gy[2][2] * tx2y2;


